function questionCard(item,answer,ctx){const q=el('div',undefined,'question-card');q.append(el('div',item.prompt,'qhead'));let inputs=[];if(Array.isArray(item.choices)){const opts=el('div',undefined,'options'),radioName=`q-${slides.length}-${Math.random()}`;item.choices.forEach((sourceChoice,i)=>{const choice=String.fromCharCode(65+i)+'. '+sourceChoice.replace(/^(?:[A-Z]\.\s*)+/,'');const label=el('label',undefined,'choice-row'),radio=document.createElement('input');radio.type='radio';radio.name=radioName;radio.value=(choice.match(/^([A-Z])\./)||[])[1]||choice;label.append(radio,el('span',choice));opts.append(label);inputs.push(radio);radio.onchange=()=>{if(radio.checked)check.onclick()}});q.append(opts)}else{const input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.className='answer-input';inputs.push(input);q.append(input)}
const feedback=el('p','','feedback');feedback.setAttribute('aria-live','polite');const answerBox=el('div',`Answer: ${answer}`,'answer'),explanation=el('div',[item.explanation,item.evidence?'Evidence: '+item.evidence:''].filter(Boolean).join('\n'),'explanation');const actions=el('div',undefined,'question-actions');const check=el('button','Check answer','primary');check.type='button';check.hidden=Array.isArray(item.choices);check.onclick=()=>{const selected=inputs.find(x=>x.type==='radio'&&x.checked),typed=inputs.find(x=>x.type==='text'),response=selected?selected.value:(typed?.value||'').trim();if(!response){feedback.textContent='Choose or type an answer first.';feedback.className='feedback';return}const expected=selected?(item.answer||''):(item.answer||answer);const numberWords={one:'1',two:'2',three:'3',four:'4',five:'5',six:'6',seven:'7',eight:'8',nine:'9',ten:'10',eleven:'11',twelve:'12',sixteen:'16',twenty:'20'};const normalize=v=>String(v).trim().toLocaleLowerCase();const wanted=normalize(expected);const acceptable=[wanted,...(item.accepted_answers||[]).map(normalize),...(typed&&numberWords[wanted]?[numberWords[wanted]]:[])];const correct=acceptable.includes(normalize(response));feedback.textContent=correct?'Correct! Well done.':'Not quite. Check the shared context and try again.';feedback.className=correct?'feedback correct':'feedback retry'};const reveal=el('button','Show answer');reveal.type='button';reveal.onclick=()=>{answerBox.classList.toggle('show');reveal.textContent=answerBox.classList.contains('show')?'Hide answer':'Show answer'};const why=el('button','Why?');why.type='button';why.onclick=()=>{explanation.classList.toggle('show');why.textContent=explanation.classList.contains('show')?'Hide explanation':'Why?'};actions.append(check,reveal,why);q.append(feedback,actions,answerBox,explanation);return q}
